import React from 'react';
import { Document, Page, pdfjs } from 'react-pdf';
import HTMLFlipBook from 'react-pageflip';
import pdfWorker from 'pdfjs-dist/build/pdf.worker.entry';
import '../App.css';

// ✅ Use local worker for compatibility
pdfjs.GlobalWorkerOptions.workerSrc = pdfWorker;

const PaperViewer = () => {
  const pdfUrl = process.env.PUBLIC_URL + '/(Final)M3_Research Paper_5pages.pdf';

  return (
    <div className="paper-section section" id="publication">
      <div className="container text-center">
        <h2 className="section-title mb-4" data-aos="fade-up">Our Publication</h2>
        <p className="mb-4" data-aos="fade-up" data-aos-delay="100">
          Published in: <strong>International Conference on Advances in Computing, Control and Telecommunication Technologies</strong>
        </p>

        <div className="pdf-flipbook-wrapper" data-aos="zoom-in">
          <HTMLFlipBook width={400} height={520} className="flipbook">
            <Document file={pdfUrl}>
              {Array.from(new Array(5), (el, index) => (
                <Page
                  key={`page_${index + 1}`}
                  pageNumber={index + 1}
                  width={400}
                />
              ))}
            </Document>
          </HTMLFlipBook>
        </div>
      </div>
    </div>
  );
};

export default PaperViewer;
